19		HookNameAgentStart      = "agent_start"
20		HookNameAgentEnd        = "agent_end"
21		HookNameSessionShutdown = "session_shutdown"
22	
23		extensionRelDir       = ".omp/extensions/entire"
24		extensionRelFile      = ".omp/extensions/entire/index.ts"
25		extensionMarker       = "// entire-agent-omp: project-local Entire integration for omp."
