30	type hookPayload struct {
31		Type        string `json:"type"`
32		CWD         string `json:"cwd,omitempty"`
33		SessionID   string `json:"session_id,omitempty"`
34		SessionFile string `json:"session_file,omitempty"`
35		SessionRef  string `json:"session_ref,omitempty"`
36		Prompt      string `json:"prompt,omitempty"`
37		UserPrompt  string `json:"user_prompt,omitempty"`
38		Model       string `json:"model,omitempty"`
