41	func (a *Agent) ParseHook(hookName string, input []byte) (*protocol.EventJSON, error) {
42		if hookName == HookNameSessionShutdown {
43			_ = clearCachedSessionID()
44			return nil, nil
45		}
46		if len(bytes.TrimSpace(input)) == 0 {
47			return nil, nil
48		}
49	
50		var payload hookPayload
51		if err := json.Unmarshal(input, &payload); err != nil {
52			return nil, fmt.Errorf("parse hook payload: %w", err)
53		}
54	
55		switch hookName {
56		case HookNameSessionStart, HookNameAgentStart, HookNameAgentEnd:
57		default:
58			return nil, nil
59		}
60	
61		sessionID := resolveSessionID(payload)
62		if sessionID == "" {
63			return nil, nil
64		}
65		if !validSessionID(sessionID) {
66			return nil, fmt.Errorf("unsafe session id %q", sessionID)
67		}
68		_ = cacheSessionID(sessionID)
69	
70		event := &protocol.EventJSON{
71			SessionID: sessionID,
72			Timestamp: time.Now().UTC().Format(time.RFC3339),
73		}
74		switch hookName {
75		case HookNameSessionStart:
76			event.Type = 1
77			event.SessionRef = hookSessionRef(payload)
78		case HookNameAgentStart:
79			event.Type = 2
80			event.SessionRef = hookSessionRef(payload)
81			event.Prompt = payload.Prompt
82			if event.Prompt == "" {
83				event.Prompt = payload.UserPrompt
84			}
85		case HookNameAgentEnd:
86			event.Type = 3
87			if source := hookSessionRef(payload); source != "" {
88				if snapshot, err := snapshotSession(source, payload.CWD, sessionID); err == nil {
89					event.SessionRef = snapshot
90					event.Model = payload.Model
91					if event.Model == "" {
92						event.Model = extractModelFromPath(snapshot)
93					}
94				}
95			}
96		}
97		return event, nil
98	}
