117	func sessionIDFromFilename(path string) string {
118		base := filepath.Base(strings.TrimSpace(path))
119		if base == "." || base == "" {
120			return ""
121		}
122		base = strings.TrimSuffix(base, filepath.Ext(base))
123		if i := strings.LastIndexByte(base, '_'); i >= 0 {
124			base = base[i+1:]
125		}
126		if !validSessionID(base) {
127			return ""
128		}
129		return base
130	}
131	
132	func validSessionID(id string) bool {
133		if id == "" || id == "." || id == ".." {
134			return false
135		}
136		for _, r := range id {
137			if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') ||
138				(r >= '0' && r <= '9') || r == '-' || r == '_' || r == '.' {
139				continue
140			}
141			return false
142		}
143		return true
144	}
