164	func readCachedSessionID() string {
165		data, err := os.ReadFile(cachedSessionPath())
166		if err != nil {
167			return ""
168		}
169		id := strings.TrimSpace(string(data))
170		if !validSessionID(id) {
171			return ""
172		}
173		return id
174	}
