184	func ensurePrivateDir(path string) error {
185		if err := os.MkdirAll(path, 0o700); err != nil {
186			return fmt.Errorf("create omp private directory: %w", err)
187		}
188		info, err := os.Lstat(path)
189		if err != nil {
190			return fmt.Errorf("inspect omp private directory: %w", err)
191		}
192		if info.Mode()&os.ModeSymlink != 0 || !info.IsDir() {
193			return fmt.Errorf("omp private path is not a directory: %s", path)
194		}
195		//nolint:gosec // Directories require execute bits; 0700 is the private-directory equivalent of 0600.
196		if err := os.Chmod(path, 0o700); err != nil {
197			return fmt.Errorf("secure omp private directory: %w", err)
198		}
199		return nil
200	}
