270	func atomicWriteFile(path string, data []byte, mode os.FileMode) error {
271		tmp, err := os.CreateTemp(filepath.Dir(path), ".write-*")
272		if err != nil {
273			return err
274		}
275		tmpName := tmp.Name()
276		defer os.Remove(tmpName)
277		if err := tmp.Chmod(mode); err != nil {
278			return errors.Join(err, tmp.Close())
279		}
280		if _, err := tmp.Write(data); err != nil {
281			return errors.Join(err, tmp.Close())
282		}
283		if err := tmp.Close(); err != nil {
284			return err
285		}
286		return os.Rename(tmpName, path)
287	}
