342	const generatedExtension = `import type { ExtensionAPI, ExtensionContext } from "@oh-my-pi/pi-coding-agent";
343	import { execFile, execFileSync } from "node:child_process";
344	
345	// entire-agent-omp: project-local Entire integration for omp.
346	export default function entireAgent(pi: ExtensionAPI): void {
347	  let turnOpen = false;
348	  let pendingPrompt: string | undefined;
349	  let runEnd: Promise<boolean> | undefined;
350	  let resolveRunEnd: ((willContinue: boolean) => void) | undefined;
351	  let deferredEnd: Record<string, unknown> | undefined;
352	  let turnIdentity: Record<string, unknown> | undefined;
353	  let sessionGeneration = 0;
354	
355	  function armRunEnd(): Promise<boolean> {
356	    if (!runEnd) {
357	      runEnd = new Promise((resolve) => {
358	        resolveRunEnd = resolve;
359	      });
360	    }
361	    return runEnd;
362	  }
363	
364	  function settleRunEnd(willContinue: boolean): void {
365	    resolveRunEnd?.(willContinue);
366	    resolveRunEnd = undefined;
367	  }
368	
369	  async function crossRunEnd(): Promise<boolean | undefined> {
370	    const generation = sessionGeneration;
371	    const barrier = armRunEnd();
372	    const willContinue = await barrier;
373	    if (generation !== sessionGeneration) return undefined;
374	    if (runEnd === barrier) runEnd = undefined;
375	    return willContinue;
376	  }
377	
378	  function runHook(name: string, payload: Record<string, unknown>, timeout = 10_000): Promise<void> {
379	    return new Promise((resolve) => {
380	      let body: string;
381	      try {
382	        body = JSON.stringify(payload);
383	      } catch {
384	        resolve();
385	        return;
386	      }
387	      try {
388	        const child = execFile(
389	          "entire",
390	          ["hooks", "omp", name],
391	          { timeout, windowsHide: true, maxBuffer: 4 * 1024 * 1024 },
392	          () => resolve(),
393	        );
394	        child.stdin?.on("error", () => resolve());
395	        child.stdin?.end(body);
396	      } catch {
397	        resolve();
398	      }
399	    });
400	  }
401	
402	  function runHookSync(name: string, payload: Record<string, unknown>, timeout = 10_000): void {
403	    let body: string;
404	    try {
405	      body = JSON.stringify(payload);
406	    } catch {
407	      return;
408	    }
409	    try {
410	      execFileSync(
411	        "entire",
412	        ["hooks", "omp", name],
413	        { input: body, timeout, windowsHide: true, maxBuffer: 4 * 1024 * 1024 },
414	      );
415	    } catch {
416	      // Hook failures must not terminate omp.
417	    }
418	  }
419	
420	  async function startSession(_event: unknown, ctx: ExtensionContext): Promise<void> {
421	    const previousEnd = turnOpen ? armRunEnd() : undefined;
422	    sessionGeneration++;
423	    pendingPrompt = undefined;
424	    if (previousEnd) {
425	      const willContinue = await previousEnd;
426	      if (willContinue && deferredEnd) runHookSync("agent_end", deferredEnd);
427	    }
428	    turnOpen = false;
429	    runEnd = undefined;
430	    resolveRunEnd = undefined;
431	    deferredEnd = undefined;
432	    turnIdentity = undefined;
433	    await runHook("session_start", {
434	      type: "session_start",
435	      cwd: ctx.cwd,
436	      session_id: ctx.sessionManager.getSessionId(),
437	      session_file: ctx.sessionManager.getSessionFile(),
438	    });
439	  }
440	
441	  pi.on("session_start", startSession);
442	  pi.on("session_switch", startSession);
443	  pi.on("session_branch", startSession);
444	
445	  pi.on("before_agent_start", (event) => {
446	    pendingPrompt = event.prompt;
447	  });
448	
449	  pi.on("agent_start", async (_event, ctx) => {
450	    if (pendingPrompt === undefined) {
451	      if (!turnOpen) return;
452	      const willContinue = await crossRunEnd();
453	      if (willContinue) {
454	        deferredEnd = undefined;
455	        armRunEnd();
456	      }
457	      return;
458	    }
459	    const prompt = pendingPrompt;
460	    pendingPrompt = undefined;
461	    if (turnOpen) {
462	      const willContinue = await crossRunEnd();
463	      if (willContinue === undefined) return;
464	      if (willContinue) {
465	        deferredEnd = undefined;
466	        armRunEnd();
467	        return;
468	      }
469	    }
470	    runEnd = undefined;
471	    deferredEnd = undefined;
472	    turnIdentity = {
473	      cwd: ctx.cwd,
474	      session_id: ctx.sessionManager.getSessionId(),
475	      session_file: ctx.sessionManager.getSessionFile(),
476	    };
477	    runHookSync("agent_start", {
478	      type: "agent_start",
479	      ...turnIdentity,
480	      prompt,
481	    });
482	    turnOpen = true;
483	    armRunEnd();
484	  });
485	
486	  pi.on("agent_end", (event) => {
487	    if (!turnOpen || !turnIdentity) return;
488	    const willContinue = event.willContinue === true;
489	    const endPayload = {
490	      type: "agent_end",
491	      ...turnIdentity,
492	      model: (event.messages.findLast((message) => message.role === "assistant") as
493	        { model?: string } | undefined)?.model,
494	    };
495	    if (!willContinue) {
496	      runHookSync("agent_end", endPayload);
497	      turnOpen = false;
498	      deferredEnd = undefined;
499	      turnIdentity = undefined;
500	    } else {
501	      deferredEnd = endPayload;
502	    }
503	    settleRunEnd(willContinue);
504	  });
505	
506	  pi.on("session_shutdown", async (_event, ctx) => {
507	    await runHook("session_shutdown", {
508	      type: "session_shutdown",
509	      cwd: ctx.cwd,
510	      session_id: ctx.sessionManager.getSessionId(),
511	      session_file: ctx.sessionManager.getSessionFile(),
512	    }, 1_500);
513	  });
514	
515	  pi.on("tool_call", (event) => {
516	    if (event.toolName !== "bash" || typeof event.input?.command !== "string") return;
517	    if (/(^|\s)GIT_TERMINAL_PROMPT\s*=/.test(event.input.command)) return;
518	    event.input.command = ` + "`export GIT_TERMINAL_PROMPT=0\n${event.input.command}`" + `;
519	  });
520	}
521	`
