16	const maxSessionHeaderBytes = 64 * 1024
17	
18	var (
19		profileNameRE            = regexp.MustCompile(`^[a-z0-9][a-z0-9._-]{0,63}$`)
20		windowsReservedProfileRE = regexp.MustCompile(`(?i)^(CON|PRN|AUX|NUL|COM[0-9]|LPT[0-9])(\..*)?$`)
21	)
22	
23	type envValue struct {
24		value string
25		set   bool
26	}
27	
28	type sessionHeader struct {
29		Type      string `json:"type"`
30		Version   int    `json:"version"`
31		ID        string `json:"id"`
32		Timestamp string `json:"timestamp"`
33		Cwd       string `json:"cwd"`
34	}
35	
36	func parseSessionHeader(data []byte) (sessionHeader, error) {
37		line, rest, ok := nextJSONLLine(data)
38		if !ok {
39			return sessionHeader{}, errors.New("parse omp session header: missing first JSONL line")
40		}
41	
42		var kind struct {
43			Type string `json:"type"`
44		}
45		if err := json.Unmarshal(line, &kind); err != nil {
46			return sessionHeader{}, fmt.Errorf("parse omp session header first line: %w", err)
47		}
48		if kind.Type == "title" {
49			line, _, ok = nextJSONLLine(rest)
50			if !ok {
51				return sessionHeader{}, errors.New("parse omp session header: title slot is not followed by a session line")
52			}
53		}
54	
55		var header sessionHeader
56		if err := json.Unmarshal(line, &header); err != nil {
57			return sessionHeader{}, fmt.Errorf("parse omp session header JSON: %w", err)
58		}
59		if header.Type != "session" {
60			return sessionHeader{}, fmt.Errorf("parse omp session header: type is %q, want %q", header.Type, "session")
61		}
62		if header.ID == "" {
63			return sessionHeader{}, errors.New("parse omp session header: id is empty")
64		}
65		if header.Version <= 0 {
66			return sessionHeader{}, fmt.Errorf("parse omp session header: version is %d, want a positive value", header.Version)
67		}
68		return header, nil
69	}
70	
71	func nextJSONLLine(data []byte) (line, rest []byte, ok bool) {
72		index := bytes.IndexByte(data, '\n')
73		if index < 0 {
74			if len(data) == 0 {
75				return nil, nil, false
76			}
77			return bytes.TrimSuffix(data, []byte{'\r'}), nil, true
78		}
79		return bytes.TrimSuffix(data[:index], []byte{'\r'}), data[index+1:], true
80	}
