101			home,
102			os.Getenv("PI_CODING_AGENT_DIR"),
103			os.Getenv("PI_CONFIG_DIR"),
104			os.Getenv("XDG_DATA_HOME"),
105			lookupEnv("OMP_PROFILE"),
106			lookupEnv("PI_PROFILE"),
107			func(path string) bool {
