119	func normalizeProfileName(profile string) string {
120		profile = strings.TrimSpace(profile)
121		if profile == "" || profile == "default" {
122			return ""
123		}
124		if profile == "." || profile == ".." || strings.HasSuffix(profile, ".") ||
125			!profileNameRE.MatchString(profile) || windowsReservedProfileRE.MatchString(profile) {
126			return ""
127		}
128		return profile
129	}
