131	func ompSessionsRootFor(
132		goos, home, agentDir, configDir, xdgData string,
133		ompProfile, piProfile envValue,
134		exists func(string) bool,
135	) (string, error) {
136		if configDir == "" {
137			configDir = ".omp"
138		}
139		baseConfigRoot := filepath.Join(home, configDir)
140		profileValue := piProfile
141		if ompProfile.set {
142			profileValue = ompProfile
143		}
144		profile := normalizeProfileName(profileValue.value)
145		configRoot := baseConfigRoot
146		if profile != "" {
147			configRoot = filepath.Join(baseConfigRoot, "profiles", profile)
148		}
149		defaultAgentDir := filepath.Join(configRoot, "agent")
150	
151		profileAgentSource := profile
152		if profileAgentSource == "" {
153			profileAgentSource = normalizeProfileName(piProfile.value)
154		}
155		switch {
156		case profile != "" || (profileAgentSource != "" && agentDir == filepath.Join(baseConfigRoot, "profiles", profileAgentSource, "agent")):
157			agentDir = defaultAgentDir
158		case agentDir == "":
159			agentDir = defaultAgentDir
160		default:
161			absolute, err := filepath.Abs(agentDir)
162			if err != nil {
163				return "", fmt.Errorf("resolve PI_CODING_AGENT_DIR: %w", err)
164			}
165			agentDir = absolute
166		}
167		if (goos == "linux" || goos == "darwin") && agentDir == defaultAgentDir && xdgData != "" {
168			appRoot := filepath.Join(xdgData, "omp")
169			xdgRoot := appRoot
170			if profile != "" {
171				xdgRoot = filepath.Join(appRoot, "profiles", profile)
172			}
173			if exists(xdgRoot) {
174				return filepath.Join(xdgRoot, "sessions"), nil
175			}
176		}
177		return filepath.Join(agentDir, "sessions"), nil
178	}
179	
180	func encodeSessionDirName(cwd string) (string, error) {
181		canonicalCwd, err := canonicalPath(cwd)
182		if err != nil {
183			return "", fmt.Errorf("resolve omp session cwd %q: %w", cwd, err)
184		}
185		home, err := os.UserHomeDir()
186		if err != nil {
187			return "", fmt.Errorf("resolve home directory: %w", err)
188		}
189		canonicalHome, err := canonicalPath(home)
190		if err != nil {
191			return "", fmt.Errorf("resolve canonical home directory: %w", err)
192		}
193		canonicalTemp, err := canonicalPath(os.TempDir())
194		if err != nil {
195			return "", fmt.Errorf("resolve canonical temporary directory: %w", err)
196		}
197	
198		if relative, ok := relativeWithin(canonicalHome, canonicalCwd); ok {
199			return encodeRelative("-", relative), nil
200		}
201		if relative, ok := relativeWithin(canonicalTemp, canonicalCwd); ok {
202			return encodeRelative("-tmp", relative), nil
203		}
204		trimmed := strings.TrimLeft(canonicalCwd, "/\\")
205		replacer := strings.NewReplacer("/", "-", "\\", "-", ":", "-")
206		return "--" + replacer.Replace(trimmed) + "--", nil
207	}
208	
209	func canonicalPath(path string) (string, error) {
210		absolute, err := filepath.Abs(path)
211		if err != nil {
212			return "", err
213		}
214		canonical, err := filepath.EvalSymlinks(absolute)
215		if err == nil {
216			return canonical, nil
217		}
218		return filepath.Clean(absolute), nil
219	}
220	
221	func relativeWithin(root, candidate string) (string, bool) {
222		relative, err := filepath.Rel(root, candidate)
223		if err != nil {
224			return "", false
225		}
226		return relative, relative == "." || (relative != ".." && !strings.HasPrefix(relative, ".."+string(filepath.Separator)) && !filepath.IsAbs(relative))
227	}
228	
229	func encodeRelative(prefix, relative string) string {
230		if relative == "." || relative == "" {
231			return prefix
232		}
233		replacer := strings.NewReplacer("/", "-", "\\", "-", ":", "-")
234		encoded := replacer.Replace(relative)
235		if strings.HasSuffix(prefix, "-") {
236			return prefix + encoded
237		}
238		return prefix + "-" + encoded
239	}
240	
241	func (a *Agent) ResolveSessionFile(sessionDir, sessionID string) string {
242		if !safeSessionID(sessionID) {
243			return ""
244		}
245		entries, _ := os.ReadDir(sessionDir)
246		exactFilename := filepath.Join(sessionDir, sessionID+".jsonl")
247		for _, entry := range entries {
248			if entry.IsDir() || filepath.Ext(entry.Name()) != ".jsonl" {
249				continue
250			}
251			path := filepath.Join(sessionDir, entry.Name())
252			header, err := readSessionHeader(path)
253			if err == nil && header.ID == sessionID {
254				return path
255			}
256		}
257		return exactFilename
258	}
259	
260	func readSessionHeader(path string) (sessionHeader, error) {
261		file, err := os.Open(path)
262		if err != nil {
263			return sessionHeader{}, err
264		}
265		defer file.Close()
266		data, err := io.ReadAll(io.LimitReader(file, maxSessionHeaderBytes))
267		if err != nil {
268			return sessionHeader{}, err
269		}
270		return parseSessionHeader(data)
271	}
272	
273	func safeSessionID(sessionID string) bool {
274		if sessionID == "" || sessionID == "." || sessionID == ".." {
275			return false
276		}
277		for _, r := range sessionID {
278			if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '.' || r == '_' || r == '-' {
279				continue
280			}
281			return false
282		}
283		return true
284	}
