72	func parseSessionEntries(data []byte, header sessionHeader) (*parsedSession, error) {
73		scanner := bufio.NewScanner(bytes.NewReader(data))
74		scanner.Buffer(make([]byte, 64*1024), maxSessionLine+1)
75		result := &parsedSession{Header: header}
76		byID := make(map[string]parsedEntry)
77		var last *parsedEntry
78		for scanner.Scan() {
79			result.Lines++
80			if len(scanner.Bytes()) > maxSessionLine {
81				return nil, fmt.Errorf("scan session: line %d exceeds %d bytes", result.Lines, maxSessionLine)
82			}
83			var kind struct {
84				Type string `json:"type"`
85			}
86			if json.Unmarshal(scanner.Bytes(), &kind) != nil {
87				continue
88			}
89			if kind.Type == "title" || kind.Type == "session" {
90				continue
91			}
92			var entry sessionEntry
93			if json.Unmarshal(scanner.Bytes(), &entry) != nil || entry.ID == "" || entry.Type == "" {
94				continue
95			}
96			record := parsedEntry{Line: result.Lines, Entry: entry}
97			result.Entries = append(result.Entries, record)
98			byID[entry.ID] = record
99			recordCopy := record
100			last = &recordCopy
101		}
102		if err := scanner.Err(); err != nil {
103			return nil, fmt.Errorf("scan session: %w", err)
104		}
105	
106		seen := make(map[string]bool)
107		for last != nil && !seen[last.Entry.ID] {
108			seen[last.Entry.ID] = true
109			result.Active = append(result.Active, *last)
110			if last.Entry.ParentID == nil || *last.Entry.ParentID == "" {
111				break
112			}
113			parent, ok := byID[*last.Entry.ParentID]
114			if !ok {
115				break
116			}
117			parentCopy := parent
118			last = &parentCopy
119		}
120		for left, right := 0, len(result.Active)-1; left < right; left, right = left+1, right-1 {
121			result.Active[left], result.Active[right] = result.Active[right], result.Active[left]
122		}
123		return result, nil
124	}
