314	func modifiedFiles(entries []parsedEntry, offset int) []string {
315		seen := make(map[string]bool)
316		files := []string{}
317		add := func(path string, trim bool) {
318			if trim {
319				path = strings.TrimSpace(path)
320			}
321			if path != "" && !strings.Contains(path, "://") && !seen[path] {
322				seen[path] = true
323				files = append(files, path)
324			}
325		}
326		for _, record := range entries {
327			message := record.Entry.Message
328			if record.Line <= offset || message == nil || message.Role != "assistant" {
329				continue
330			}
331			for _, block := range messageBlocks(message.Content) {
332				if block.Type != "toolCall" || !isWriteTool(block.Name) {
333					continue
334				}
335				var arguments map[string]any
336				if json.Unmarshal(block.Arguments, &arguments) != nil {
337					continue
338				}
339				if normalizeToolName(block.Name) == "apply_patch" {
340					input, _ := arguments["input"].(string)
341					for _, path := range patchPaths(input) {
342						add(path, false)
343					}
344					continue
345				}
346				for _, key := range []string{"path", "file_path", "filePath"} {
347					path, ok := arguments[key].(string)
348					if ok {
349						add(path, true)
350					}
351				}
352			}
353		}
354		return files
355	}
